#include <stdlib.h>

typedef struct {
    long long s;
    long long t;
} Line;

int cmpLine(const void *a, const void *b) {
    const Line *x = (const Line *)a;
    const Line *y = (const Line *)b;

    if (x->s < y->s) return -1;
    if (x->s > y->s) return 1;
    if (x->t > y->t) return -1;
    if (x->t < y->t) return 1;
    return 0;
}

long long countPairs(long long *a, long long *tmp, int l, int r) {
    if (r - l <= 1) return 0;

    int m = (l + r) / 2;
    long long ans = 0;

    ans += countPairs(a, tmp, l, m);
    ans += countPairs(a, tmp, m, r);

